import * as THREE from 'three';
import { buildBinaryMask, labelComponents, traceLoops, groupLoops } from '../src/lib/contour';
import { simplifyClosedLoop, chaikinClosed } from '../src/lib/rdp';
import type { Point } from '../src/lib/types';

function makeGearImage(size: number): Uint8ClampedArray {
  const data = new Uint8ClampedArray(size * size * 4);
  data.fill(255);
  const cx = size / 2;
  const cy = size / 2;
  const teeth = 10;
  const rOuter = size * 0.4;
  const rInner = size * 0.32;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = x - cx;
      const dy = y - cy;
      const r = Math.hypot(dx, dy);
      const a = Math.atan2(dy, dx);
      const toothPhase = ((a + Math.PI) / (Math.PI * 2)) * teeth;
      const inTooth = toothPhase % 1 < 0.5;
      const limit = inTooth ? rOuter : rInner;
      const isHub = r < size * 0.08;
      const filled = r < limit && !isHub;
      const idx = (y * size + x) * 4;
      const v = filled ? 0 : 255;
      data[idx] = v; data[idx+1]=v; data[idx+2]=v; data[idx+3]=255;
    }
  }
  return data;
}

function countOpenEdges(positions: Float32Array): number {
  const eps = 1e-4;
  const q = (v: number) => Math.round(v / eps);
  const posKeyToId = new Map<string, number>();
  const vertexCount = positions.length / 3;
  const remap = new Int32Array(vertexCount);
  for (let i = 0; i < vertexCount; i++) {
    const key = `${q(positions[i*3])}_${q(positions[i*3+1])}_${q(positions[i*3+2])}`;
    let id = posKeyToId.get(key);
    if (id === undefined) { id = posKeyToId.size; posKeyToId.set(key, id); }
    remap[i] = id;
  }
  const edgeCount = new Map<string, number>();
  const triCount = vertexCount / 3;
  for (let t = 0; t < triCount; t++) {
    const a = remap[t*3], b = remap[t*3+1], c = remap[t*3+2];
    const edges: [number,number][] = [[a,b],[b,c],[c,a]];
    for (const [x,y] of edges) {
      const key = x < y ? `${x}_${y}` : `${y}_${x}`;
      edgeCount.set(key, (edgeCount.get(key)||0)+1);
    }
  }
  let open = 0;
  edgeCount.forEach(v => { if (v !== 2) open++; });
  return open;
}

function run(teeth: number, size: number, bevel: number, label: string) {
  const data = makeGearImage(size);
  const threshold = { threshold: 128, invert: false, minIslandArea: 24 };
  const mask0 = buildBinaryMask(data, size, size, threshold.threshold, threshold.invert);
  const { labels, areas } = labelComponents(mask0, size, size);
  const mask = new Uint8Array(size*size);
  for (let i=0;i<size*size;i++){ const lb=labels[i]; if(lb>=0 && areas[lb]>=threshold.minIslandArea) mask[i]=1; }
  const rawLoops = traceLoops(mask, size, size);
  const processed: Point[][] = rawLoops.map(loop => simplifyClosedLoop(chaikinClosed(loop,1), 1.2));
  const groups = groupLoops(processed);
  let minX=Infinity,minY=Infinity,maxX=-Infinity,maxY=-Infinity;
  for(const g of groups) for(const p of g.outer){ if(p.x<minX)minX=p.x; if(p.x>maxX)maxX=p.x; if(p.y<minY)minY=p.y; if(p.y>maxY)maxY=p.y; }
  const bboxW=maxX-minX, bboxH=maxY-minY;
  const scale = 80/bboxW;
  const toVec=(p:Point)=>new THREE.Vector2((p.x-minX)*scale,(bboxH-(p.y-minY))*scale);
  const depth=6;
  const geometries: THREE.BufferGeometry[]=[];
  for(const g of groups){
    const shape=new THREE.Shape(g.outer.map(toVec));
    for(const h of g.holes) shape.holes.push(new THREE.Path(h.map(toVec)));
    const eg=new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:bevel>0,bevelThickness:bevel,bevelSize:bevel,bevelSegments:3,steps:1,curveSegments:8});
    geometries.push(eg);
  }
  let vertCount=0;
  for(const g of geometries) vertCount+=g.getAttribute('position').count;
  const positions=new Float32Array(vertCount*3);
  let vOff=0;
  for(const g of geometries){ const p=g.getAttribute('position') as THREE.BufferAttribute; positions.set(p.array as Float32Array, vOff*3); vOff+=p.count; }
  const bb=new THREE.BufferGeometry(); bb.setAttribute('position', new THREE.BufferAttribute(positions,3)); bb.computeBoundingBox();
  const box=bb.boundingBox!;
  const openEdges=countOpenEdges(positions);
  console.log(`[${label}] islands=${areas.length} rawLoops=${rawLoops.length} groups=${groups.length} holes=${groups.map(g=>g.holes.length)} bbox=${(box.max.x-box.min.x).toFixed(2)}x${(box.max.y-box.min.y).toFixed(2)}x${(box.max.z-box.min.z).toFixed(2)} tris=${positions.length/9} openEdges=${openEdges} watertight=${openEdges===0}`);
}

run(10, 256, 0.4, 'gear w/ bevel');
run(10, 256, 0, 'gear no bevel');
run(10, 512, 0.4, 'gear 512 w/ bevel');
